namespace ZapretGui;
sealed partial class MainForm
{
 void ArrangeBrowser(TabControl tabs)
 {
  var page=tabs.TabPages[2];var flows=page.Controls.OfType<FlowLayoutPanel>().ToArray();var body=flows.First(x=>x.Dock==DockStyle.Fill);var header=flows.First(x=>x.Dock==DockStyle.Top);
  var browser=body.Controls.OfType<ComboBox>().First();var profiles=body.Controls.OfType<ComboBox>().Last();var port=body.Controls.OfType<NumericUpDown>().First();var results=body.Controls.OfType<ListBox>().First();var actions=body.Controls.OfType<Button>().ToArray();var addButtons=header.Controls.OfType<FlowLayoutPanel>().First().Controls.OfType<Button>().ToArray();var hint=body.Controls.OfType<Label>().Last();
  var layout=new TableLayoutPanel(){Dock=DockStyle.Fill,ColumnCount=2,RowCount=1,BackColor=Background};layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,62));layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,38));
  var left=new TableLayoutPanel(){Dock=DockStyle.Fill,ColumnCount=1,RowCount=3,Padding=new Padding(16),BackColor=Surface,Margin=new Padding(0,0,16,0)};left.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));left.RowStyles.Add(new RowStyle(SizeType.Absolute,265));left.RowStyles.Add(new RowStyle(SizeType.Percent,100));left.RowStyles.Add(new RowStyle(SizeType.Absolute,65));
  var controls=new FlowLayoutPanel(){Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=false,BackColor=Surface};left.Controls.Add(controls,0,0);
  controls.Controls.Add(new Label(){Text="Сайты из браузера",AutoSize=true,Font=new Font("Segoe UI Semibold",17),ForeColor=Ink,Margin=new Padding(0,0,0,12)});
  var browsers=new FlowLayoutPanel(){Height=48,Width=600,BackColor=Surface,WrapContents=false};controls.Controls.Add(browsers);var buttons=new List<PillButton>();foreach(var name in browser.Items.Cast<string>()){var button=new PillButton(){Text=name,Width=100,Height=36,Margin=new Padding(0,0,8,0),Active=browser.Text==name};buttons.Add(button);browsers.Controls.Add(button);button.Click+=(_,_)=>{browser.SelectedItem=name;foreach(var b in buttons){b.Active=b==button;b.Invalidate();}};}
  var hidden=new Panel(){Visible=false};Controls.Add(hidden);hidden.Controls.Add(browser);hidden.Controls.Add(profiles);
  var portRow=new FlowLayoutPanel(){Height=36,Width=600,BackColor=Surface};portRow.Controls.Add(new Label(){Text="CDP порт",AutoSize=true,ForeColor=Ink,Margin=new Padding(0,4,12,0)});port.Width=100;portRow.Controls.Add(port);controls.Controls.Add(portRow);
  var actionRow=new FlowLayoutPanel(){Height=98,Width=600,WrapContents=true,BackColor=Surface};controls.Controls.Add(actionRow);foreach(var b in actions){actionRow.Controls.Add(b);b.AutoSize=false;b.Width=TextRenderer.MeasureText(b.Text,b.Font).Width+36;b.Height=38;b.Margin=new Padding(0,0,8,8);}

  results.Dock=DockStyle.Fill;results.BorderStyle=BorderStyle.None;results.BackColor=Surface;results.Margin=Padding.Empty;left.Controls.Add(results,0,1);hint.Dock=DockStyle.Fill;hint.Width=550;hint.AutoSize=false;hint.Margin=new Padding(0,12,0,0);hint.UseCompatibleTextRendering=true;hint.Text="Выберите сайт в списке, чтобы добавить его справа. Для открытых вкладок Chromium должен быть запущен с отладкой CDP. Firefox поддерживает чтение истории.";left.Controls.Add(hint,0,2);
  var right=new FlowLayoutPanel(){Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=false,Padding=new Padding(18),BackColor=Surface,Margin=Padding.Empty};right.Controls.Add(new Label(){Text="Добавить сайт",Font=new Font("Segoe UI Semibold",17),ForeColor=Ink,AutoSize=true,Margin=new Padding(0,0,0,14)});var description=new Label(){UseCompatibleTextRendering=true,Text="Введите домен или ссылку.\nМожно выбрать сайт в списке слева.",Height=55,ForeColor=Color.FromArgb(180,174,189),Margin=new Padding(0,0,0,12)};right.Controls.Add(description);right.Controls.Add(domain);domain.Margin=new Padding(0,0,0,18);foreach(var b in addButtons){right.Controls.Add(b);b.AutoSize=false;b.Height=42;b.Margin=new Padding(0,0,0,12);if(b.Text=="Через Zapret")b.BackColor=Accent;}
  layout.Controls.Add(left,0,0);layout.Controls.Add(right,1,0);page.Controls.Add(layout);layout.BringToFront();
  right.AutoScroll=true;
  void Fit(){var width=Math.Max(100,right.ClientSize.Width-right.Padding.Horizontal-18);description.Width=width;domain.Width=width;foreach(var b in addButtons)b.Width=width;var lw=Math.Max(200,left.ClientSize.Width-left.Padding.Horizontal-6);browsers.Width=lw;foreach(var b in buttons)b.Width=Math.Max(46,(lw-32)/4);portRow.Width=lw;actionRow.Width=lw;profiles.Width=lw;foreach(var b in actions)b.Width=Math.Min(lw,TextRenderer.MeasureText(b.Text,b.Font).Width+36);actionRow.PerformLayout();var actionHeight=actions.Max(b=>b.Bottom)+8;actionRow.Height=actionHeight;left.RowStyles[0].Height=48+48+36+actionHeight+8;}
  layout.SizeChanged+=(_,_)=>Fit();right.SizeChanged+=(_,_)=>Fit();left.SizeChanged+=(_,_)=>Fit();Fit();body.Dispose();header.Dispose();page.Padding=Padding.Empty;
 }
}
